import sailpoint.object.Identity;
import sailpoint.object.Link;
import sailpoint.object.Application;
import sailpoint.api.IdentityService;

Identity identity = context.getObjectByName(Identity.class, identityName);
if (identity != null) {
   Application application = context.getObjectByName(Application.class, "ADDirectDemodata");
   if (application == null) return null;

   // Remove the pwdLastSet attribute from the source link. Helps avoid cyclical refresh shenanigans
  IdentityService idSvc = new IdentityService(context);
  List<Link> links = idSvc.getLinks(identity, application);
  for (Link link : links) {
    link.setAttribute("pwdLastSet", null);
  }
  identity.setAttribute("adPwdLastSet", null);
  context.saveObject(identity);
  context.commitTransaction();
}

return identity;
